def pack_circles(n: int) -> np.ndarray:
    """
    Pack n circles in a unit square to maximize sum of radii.

    Args:
        n: Number of circles to pack

    Returns:
        Numpy array of shape (n, 3) where each row is (x, y, radius)
        All values should be between 0 and 1
        Circles must not overlap

    Important: Set "all" random seeds to 2025, including the packages (such as scipy sub-packages) involving random seeds.
    """
    if n == 0:
        return np.zeros((0, 3))

    circles = np.zeros((n, 3))
    circles[0] = [0.5, 0.5, 0.5]

    for i in range(1, n):
        def max_radius(xy):
            x, y = xy
            if i == 0:
                return min(x, 1 - x, y, 1 - y)
            existing = circles[:i, :2]
            radii = circles[:i, 2]
            distances = np.sqrt((existing[:, 0] - x)**2 + (existing[:, 1] - y)**2)
            min_dist = np.min(distances - radii)
            return min(min_dist, x, 1 - x, y, 1 - y)

        def neg_max_radius(xy):
            return -max_radius(xy)

        best_r = 0
        best_pos = None

        for _ in range(10):
            initial_guess = np.random.rand(2)
            res = minimize(neg_max_radius, initial_guess, method='L-BFGS-B', bounds=[(0, 1), (0, 1)])
            if -res.fun > best_r:
                best_r = -res.fun
                best_pos = res.x

        circles[i] = [best_pos[0], best_pos[1], best_r]

    return circles

