def pack_circles(n: int) -> np.ndarray:
    """
    Pack n circles in a unit square to maximize sum of radii.

    Args:
        n: Number of circles to pack

    Returns:
        Numpy array of shape (n, 3) where each row is (x, y, radius)
        All values should be between 0 and 1
        Circles must not overlap

    Important: Set "all" random seeds to 2025, including the packages (such as scipy sub-packages) involving random seeds.
    """
    np.random.seed(2025)
    if n == 0:
        return np.zeros((0, 3))

    def objective(r, positions):
        return -np.sum(r)

    def constraint(positions_r, idx):
        positions = positions_r[:2*n].reshape(-1, 2)
        r = positions_r[2*n:]

        x, y = positions[idx]
        radius = r[idx]

        constraints = []
        constraints.append(x - radius)  # Left boundary
        constraints.append(1 - x - radius)  # Right boundary
        constraints.append(y - radius)  # Bottom boundary
        constraints.append(1 - y - radius)  # Top boundary

        for i in range(n):
            if i != idx:
                dx = positions[i, 0] - x
                dy = positions[i, 1] - y
                dist = np.sqrt(dx**2 + dy**2)
                constraints.append(dist - r[i] - radius)

        return min(constraints)

    positions = np.random.rand(n, 2)
    r = np.zeros(n)

    for i in range(n):
        def opt_func(x):
            return objective(x, positions)

        constraints = [{'type': 'ineq', 'fun': lambda x, i=i: constraint(np.concatenate([positions.flatten(), x]), i)}]

        res = minimize(opt_func, r, method='SLSQP', constraints=constraints, bounds=[(0, 1)]*n)
        r = res.x

    return np.column_stack([positions, r])

