            if len(circles) >= n:
                break
            x = (0.5 + j) / (k + 1)
            y = (0.5 + i * np.sqrt(3)/2) / (k + 1)
            if i % 2 == 1:
                x += 0.5 / (k + 1)
            circles.append([x, y, 0])

