            self.children = []
            self.max_r = min((x1 - x0)/2, (y1 - y0)/2)

        def insert(self, cx, cy, cr):
            if not self.children:
                return True

            for child in self.children:
                if child.x0 <= cx <= child.x1 and child.y0 <= cy <= child.y1:
                    return child.insert(cx, cy, cr)
            return False

        def split(self):
            x_mid = (self.x0 + self.x1) / 2
            y_mid = (self.y0 + self.y1) / 2
            self.children = [
                QuadNode(self.x0, self.y0, x_mid, y_mid),
                QuadNode(x_mid, self.y0, self.x1, y_mid),
                QuadNode(self.x0, y_mid, x_mid, self.y1),
                QuadNode(x_mid, y_mid, self.x1, self.y1)
            ]
            for child in self.children:
                child.max_r = min((child.x1 - child.x0)/2, (child.y1 - child.y0)/2)

    root = QuadNode(0, 0, 1, 1)

    for i in range(n):
        if i == 0:
            circles[i] = [0.5, 0.5, 0.5]
            root.split()
            continue

        best_r = 0
        best_pos = (0, 0)

        stack = [root]
        while stack:
            node = stack.pop()
            if node.max_r <= best_r:
                continue

            if not node.children:
                cx = (node.x0 + node.x1) / 2
                cy = (node.y0 + node.y1) / 2

