                r = min(min_dist, boundary_dist)

                if r > best_r:
                    best_r = r
                    best_pos = (cx, cy)
            else:
                stack.extend(node.children)

        if best_r > 0:
            circles[i] = [best_pos[0], best_pos[1], best_r]

