    """
    np.random.seed(2025)
    if n == 0:
        return np.zeros((0, 3))

    # Initial random placement
    circles = np.random.rand(n, 2)
    radii = np.zeros(n)

    # Optimization function
    def objective(r, centers):
        return -np.sum(r)

    def constraint(r, centers, i):
        x, y = centers[i]
        ri = r[i]
        constraints = [
            x - ri,
            1 - x - ri,
            y - ri,
            1 - y - ri
        ]
        for j in range(n):
            if i != j:
                dist = np.sqrt((centers[i,0]-centers[j,0])**2 + (centers[i,1]-centers[j,1])**2)
                constraints.append(dist - ri - r[j])
        return np.array(constraints)

    # Optimize radii with current centers
    bounds = [(0, 0.5) for _ in range(n)]
    constraints = [{'type': 'ineq', 'fun': lambda r: constraint(r, circles, i)} for i in range(n)]
    res = minimize(objective, np.zeros(n), args=(circles,), bounds=bounds, constraints=constraints)
    radii = res.x

    # Optimize positions with current radii
    for _ in range(50):
        for i in range(n):
            def pos_obj(pos):
                x, y = pos
                penalty = 0
                if x < radii[i] or x > 1 - radii[i] or y < radii[i] or y > 1 - radii[i]:
                    penalty += 1000
                for j in range(n):
                    if i != j:
                        dist = np.sqrt((x - circles[j,0])**2 + (y - circles[j,1])**2)
                        if dist < radii[i] + radii[j]:
                            penalty += 1000 * (radii[i] + radii[j] - dist)
