            res = minimize(pos_obj, circles[i], method='L-BFGS-B', bounds=[(radii[i], 1-radii[i]), (radii[i], 1-radii[i])])
            circles[i] = res.x

        # Re-optimize radii
        res = minimize(objective, radii, args=(circles,), bounds=bounds, constraints=constraints)
        radii = res.x

    return np.column_stack((circles, radii))

