def pack_circles(n: int) -> np.ndarray:
    """
    Pack n circles in a unit square to maximize sum of radii.

    Args:
        n: Number of circles to pack

    Returns:
        Numpy array of shape (n, 3) where each row is (x, y, radius)
        All values should be between 0 and 1
        Circles must not overlap

    Important: Set "all" random seeds to 2025, including the packages (such as scipy sub-packages) involving random seeds.
    """
    np.random.seed(2025)
    if n == 0:
        return np.zeros((0, 3))

    # Initialize with small circles at random positions
    circles = np.random.uniform(0, 1, (n, 2))
    radii = np.full(n, 0.001)

    # Physics simulation parameters
    max_iter = 1000
    cooling_factor = 0.99
    temperature = 1.0

    for iteration in range(max_iter):
        moved = False
        for i in range(n):
            # Calculate repulsion forces from other circles
            force = np.zeros(2)
            for j in range(n):
                if i == j:
                    continue
                diff = circles[i] - circles[j]
                dist = np.linalg.norm(diff)
                min_dist = radii[i] + radii[j]
                if dist < min_dist:
                    force += diff / (dist + 1e-8) * (min_dist - dist)

            # Add boundary repulsion
            for dim in [0, 1]:
                if circles[i, dim] < radii[i]:
                    force[dim] += (radii[i] - circles[i, dim])
                if circles[i, dim] > 1 - radii[i]:
                    force[dim] -= (circles[i, dim] - (1 - radii[i]))

            # Apply movement with temperature
            if np.linalg.norm(force) > 0:
                circles[i] += temperature * force / (np.linalg.norm(force) + 1e-8) * 0.01
                circles[i] = np.clip(circles[i], 0, 1)
                moved = True

        # Gradually increase radii if no overlaps
        if not moved or iteration > max_iter // 2:
            for i in range(n):
                # Find maximum possible radius
                min_dist = min(circles[i, 0], circles[i, 1], 
                              1 - circles[i, 0], 1 - circles[i, 1])
                for j in range(n):
                    if i == j:
                        continue
                    dist = np.linalg.norm(circles[i] - circles[j])
                    min_dist = min(min_dist, dist - radii[j])

                if min_dist > radii[i]:
                    radii[i] = min(radii[i] + temperature * 0.01, min_dist)

        temperature *= cooling_factor
        if temperature < 1e-4:
            break

    return np.column_stack((circles, radii))

