def pack_circles(n: int) -> np.ndarray:
    """
    Pack n circles in a unit square to maximize sum of radii.

    Args:
        n: Number of circles to pack

    Returns:
        Numpy array of shape (n, 3) where each row is (x, y, radius)
        All values should be between 0 and 1
        Circles must not overlap

    Important: Set "all" random seeds to 2025, including the packages (such as scipy sub-packages) involving random seeds.
    """
    np.random.seed(2025)
    if n == 0:
        return np.zeros((0, 3))

    circles = np.zeros((n, 3))

    # Initial placement using Poisson disc sampling-like approach
    for i in range(n):
        if i == 0:
            x, y = 0.5, 0.5
        else:
            best_dist = -1
            for _ in range(100):
                candidate = np.random.rand(2)
                min_dist = min(
                    min(candidate[0], 1 - candidate[0]),
                    min(candidate[1], 1 - candidate[1])
                )
                for j in range(i):
                    dist = np.sqrt(np.sum((candidate - circles[j,:2])**2)) - circles[j,2]
                    min_dist = min(min_dist, dist)
                if min_dist > best_dist:
                    best_dist = min_dist
                    x, y = candidate

        circles[i,:2] = x, y

    # Optimization to maximize radii
    def objective(r):
        return -np.sum(r)

    def constraint(r):
        for i in range(n):
            x1, y1 = circles[i,:2]
            r1 = r[i]
            # Boundary constraints
            if x1 - r1 < 0 or x1 + r1 > 1 or y1 - r1 < 0 or y1 + r1 > 1:
                return -1
            # Pairwise constraints
            for j in range(i+1, n):
                x2, y2 = circles[j,:2]
                r2 = r[j]
                dist = np.sqrt((x1-x2)**2 + (y1-y2)**2)
                if dist < r1 + r2:
                    return -1
        return 1

    constraints = {'type': 'ineq', 'fun': constraint}
    res = minimize(objective, np.ones(n)*0.1, method='SLSQP', 
                   bounds=[(0, 0.5)]*n, constraints=constraints)

