def pack_circles(n: int) -> np.ndarray:
    """
    Pack n circles in a unit square to maximize sum of radii.

    Args:
        n: Number of circles to pack

    Returns:
        Numpy array of shape (n, 3) where each row is (x, y, radius)
        All values should be between 0 and 1
        Circles must not overlap

    Important: Set "all" random seeds to 2025, including the packages (such as scipy sub-packages) involving random seeds.
    """
    np.random.seed(2025)
    if n == 0:
        return np.zeros((0, 3))

    circles = []
    quadtree = []

    def get_largest_empty_region():
        if not quadtree:
            return (0.5, 0.5, 0.5)
        regions = []
        for node in quadtree:
            x, y, size = node
            regions.append((size, x, y, size))
        regions.sort(reverse=True)
        return regions[0][1:] if regions else None

    def split_quadtree(x, y, r):
        new_nodes = []
        for node in quadtree:
            nx, ny, nsize = node
            if not (abs(nx - x) < (nsize + r) and abs(ny - y) < (nsize + r)):
                new_nodes.append(node)
            else:
                half = nsize / 2
                quarters = [
                    (nx - half/2, ny - half/2, half),
                    (nx - half/2, ny + half/2, half),
                    (nx + half/2, ny - half/2, half),
                    (nx + half/2, ny + half/2, half)
                ]
                new_nodes.extend(quarters)
        return new_nodes

    quadtree.append((0.5, 0.5, 0.5))

    for _ in range(n):
        best_x, best_y, best_r = 0, 0, 0

        region = get_largest_empty_region()
        if region:
            x, y, size = region
            if not circles:
                r = min(x, y, 1-x, 1-y)
                best_x, best_y, best_r = x, y, r
            else:
                tree = cKDTree([c[:2] for c in circles])
                dists, _ = tree.query([(x, y)], k=1)
                r = min(dists[0], size, x, y, 1-x, 1-y)
                if r > best_r:
                    best_x, best_y, best_r = x, y, r

        quadtree = split_quadtree(best_x, best_y, best_r)
        circles.append([best_x, best_y, best_r])

    return np.array(circles)

