def pack_circles(n: int) -> np.ndarray:
    """
    Pack n circles in a unit square to maximize sum of radii.

    Args:
        n: Number of circles to pack

    Returns:
        Numpy array of shape (n, 3) where each row is (x, y, radius)
        All values should be between 0 and 1
        Circles must not overlap

    Important: Set "all" random seeds to 2025, including the packages (such as scipy sub-packages) involving random seeds.
    """
    np.random.seed(2025)
    if n == 0:
        return np.zeros((0, 3))

    # Initial random placement with small radii
    circles = np.random.uniform(0.1, 0.9, (n, 2))
    radii = np.full(n, 0.01)

    def objective(r):
        total = -np.sum(r)  # Maximize sum of radii
        penalty = 0

        # Boundary constraints
        for i in range(n):
            x, y = circles[i]
            min_dist = min(x, 1-x, y, 1-y)
            if r[i] > min_dist:
                penalty += 1000 * (r[i] - min_dist)**2

        # Overlap constraints
        for i in range(n):
            for j in range(i+1, n):
                dist = np.sqrt((circles[i][0]-circles[j][0])**2 + (circles[i][1]-circles[j][1])**2)
                if dist < r[i] + r[j]:
                    penalty += 1000 * (r[i] + r[j] - dist)**2

        return total + penalty

    # Optimize radii with current positions
    bounds = [(0.01, 1)] * n
    res = minimize(objective, radii, bounds=bounds)
    radii = res.x

    # Position optimization with simulated annealing
    for temp in np.logspace(2, -2, 100):
        for i in range(n):
            def pos_obj(pos):
                x, y = pos
                min_dist = min(x, 1-x, y, 1-y)
                if radii[i] > min_dist:
                    return float('inf')

                penalty = 0
                for j in range(n):
                    if i == j:
                        continue
                    dist = np.sqrt((x-circles[j][0])**2 + (y-circles[j][1])**2)
                    if dist < radii[i] + radii[j]:
                        penalty += (radii[i] + radii[j] - dist)**2

                return penalty

            new_pos = circles[i] + np.random.normal(0, temp, 2)
            new_pos = np.clip(new_pos, 0, 1)
            if pos_obj(new_pos) < pos_obj(circles[i]):
                circles[i] = new_pos

    # Final radius optimization
    res = minimize(objective, radii, bounds=bounds)
    radii = res.x

    return np.column_stack([circles, radii])

