        size = 1.0 / (2 ** level)
        return (int(x / size), int(y / size), level)

    def add_to_quadtree(x, y, r):
        level = 0
        while True:
            qx, qy, lvl = get_quadrant(x, y, level)
            key = (qx, qy, lvl)
            if key not in quadtree:
                quadtree[key] = []
            quadtree[key].append((x, y, r))
            if len(quadtree[key]) <= 4 or level >= 8:
                break
            level += 1

    def get_nearby_candidates(x, y, level, density):
        candidates = []
        size = 1.0 / (2 ** level)
        for dx in [-1, 0, 1]:
            for dy in [-1, 0, 1]:
                qx, qy = int(x / size) + dx, int(y / size) + dy
                key = (qx, qy, level)
                if key in quadtree:
                    for (cx, cy, cr) in quadtree[key]:
                        theta = np.random.uniform(0, 2*np.pi, density)
                        offset = 1.5 * cr
                        new_points = np.column_stack([
                            cx + offset * np.cos(theta),
                            cy + offset * np.sin(theta)
                        ])
                        candidates.extend(new_points.clip(0, 1))
        return candidates

    for _ in range(n):
        best_score = -1
        best_pos = (0.5, 0.5)
        best_r = 0

