                density = min(8, max(2, int(10 * r)))
                candidates.extend(get_nearby_candidates(x, y, 0, density))
                candidates.extend(get_nearby_candidates(x, y, 1, density//2))
        else:
            candidates = np.random.uniform(0, 1, (20, 2))

        boundary_density = min(15, max(5, n))
