    Pack n circles in a unit square to maximize sum of radii.

    Args:
        n: Number of circles to pack

    Returns:
        Numpy array of shape (n, 3) where each row is (x, y, radius)
        All values should be between 0 and 1
        Circles must not overlap

    Important: Set "all" random seeds to 2025, including the packages (such as scipy sub-packages) involving random seeds.
    """
    np.random.seed(2025)
    if n == 0:
        return np.zeros((0, 3))

    circles = []
    quad_tree = {'x0': 0, 'y0': 0, 'x1': 1, 'y1': 1, 'children': []}
    heap = [(-1.0, quad_tree)]

    for _ in range(n):
        while heap:
            neg_size, node = heapq.heappop(heap)
            size = -neg_size

            if 'children' not in node:
                x, y = (node['x0'] + node['x1']) / 2, (node['y0'] + node['y1']) / 2
                r = min(size/2, x - node['x0'], node['x1'] - x, y - node['y0'], node['y1'] - y)

                valid = True
                for cx, cy, cr in circles:
                    if np.sqrt((cx - x)**2 + (cy - y)**2) < cr + r:
                        valid = False
                        break

                if valid:
                    circles.append([x, y, r])
                    break
                else:
                    continue

            for child in node['children']:
                child_size = min(child['x1'] - child['x0'], child['y1'] - child['y0'])
                heapq.heappush(heap, (-child_size, child))

        # Update quadtree
        quad_tree = {'x0': 0, 'y0': 0, 'x1': 1, 'y1': 1, 'children': []}
        heap = []

        for cx, cy, cr in circles:
            def split(node):
                if 'children' in node:
                    for child in node['children']:
                        split(child)
                    return

                if (node['x0'] >= cx + cr or node['x1'] <= cx - cr or
                    node['y0'] >= cy + cr or node['y1'] <= cy - cr):
                    return

                mx, my = (node['x0'] + node['x1'])/2, (node['y0'] + node['y1'])/2
                node['children'] = [
                    {'x0': node['x0'], 'y0': node['y0'], 'x1': mx, 'y1': my},
                    {'x0': mx, 'y0': node['y0'], 'x1': node['x1'], 'y1': my},
                    {'x0': node['x0'], 'y0': my, 'x1': mx, 'y1': node['y1']},
                    {'x0': mx, 'y0': my, 'x1': node['x1'], 'y1': node['y1']}
                ]
                for child in node['children']:
                    split(child)

            split(quad_tree)

        def collect_empty(node):
            if 'children' in node:
                for child in node['children']:
                    yield from collect_empty(child)
            else:
                size = min(node['x1'] - node['x0'], node['y1'] - node['y0'])
                heapq.heappush(heap, (-size, node))

        collect_empty(quad_tree)

    # Final jittering optimization
    for _ in range(100):
        for i in range(len(circles)):
            x, y, r = circles[i]
            best_r = r
            best_pos = (x, y)

            for _ in range(5):
                dx, dy = np.random.uniform(-0.01, 0.01, 2)
                new_x = np.clip(x + dx, 0, 1)
                new_y = np.clip(y + dy, 0, 1)

                min_dist = min(new_x, 1 - new_x, new_y, 1 - new_y)
                for j in range(len(circles)):
                    if i == j:
                        continue
                    cx, cy, cr = circles[j]
