    points = np.random.uniform(0.1, 0.9, size=(2, 2))
    for i in range(2, n):
        vor = Voronoi(points)
        max_dist = -1
        best_point = None
        for vertex in vor.vertices:
            if 0 <= vertex[0] <= 1 and 0 <= vertex[1] <= 1:
                dist = np.min(np.sum((points - vertex)**2, axis=1))
                if dist > max_dist:
                    max_dist = dist
                    best_point = vertex
        if best_point is None:
            best_point = np.random.uniform(0.1, 0.9, size=2)
        points = np.vstack([points, best_point])

    # Assign initial radii
    for i in range(n):
        min_dist = min(points[i,0], 1-points[i,0], points[i,1], 1-points[i,1])
        for j in range(n):
            if i == j:
                continue
            dist = np.sqrt(np.sum((points[i] - points[j])**2))
            if dist < min_dist:
                min_dist = dist
        circles[i,:2] = points[i]
        circles[i,2] = min_dist * 0.5

    # Iterative refinement
    for _ in range(100):
        for i in range(n):
            # Find neighbors
            neighbors = []
            for j in range(n):
                if i == j:
                    continue
                dist = np.sqrt(np.sum((circles[i,:2] - circles[j,:2])**2))
                if dist < 2 * (circles[i,2] + circles[j,2]):
                    neighbors.append(j)

            # Push away from neighbors and boundaries
            force = np.zeros(2)
            for j in neighbors:
                vec = circles[i,:2] - circles[j,:2]
                dist = np.sqrt(np.sum(vec**2))
                overlap = circles[i,2] + circles[j,2] - dist
                if overlap > 0:
                    force += 0.1 * overlap * vec / (dist + 1e-6)

            # Boundary repulsion
            boundary_force = np.array([
                max(0, 0.1 - circles[i,0]) - max(0, circles[i,0] - 0.9),
                max(0, 0.1 - circles[i,1]) - max(0, circles[i,1] - 0.9)
            ]) * 0.2

            circles[i,:2] += force + boundary_force
            circles[i,:2] = np.clip(circles[i,:2], 0, 1)

            # Update radius
            min_dist = min(circles[i,0], 1-circles[i,0], circles[i,1], 1-circles[i,1])
            for j in neighbors:
                dist = np.sqrt(np.sum((circles[i,:2] - circles[j,:2])**2))
