def pack_circles(n: int) -> np.ndarray:
    """
    Pack n circles in a unit square to maximize sum of radii.

    Args:
        n: Number of circles to pack

    Returns:
        Numpy array of shape (n, 3) where each row is (x, y, radius)
        All values should be between 0 and 1
        Circles must not overlap

    Important: Set "all" random seeds to 2025, including the packages (such as scipy sub-packages) involving random seeds.
    """
    import numpy as np
    from scipy.spatial import Voronoi

    np.random.seed(2025)
    if n == 0:
        return np.zeros((0, 3))

    # Poisson disk sampling with variable radii
    circles = np.zeros((n, 3))
    active = []
    first_point = np.random.uniform(0, 1, 2)
    circles[0, :2] = first_point
    circles[0, 2] = 0.1
    active.append(0)

    k = 30
    for i in range(1, n):
        best_r = 0
        best_pos = np.zeros(2)

        for j in range(k):
            idx = np.random.choice(active)
            angle = np.random.uniform(0, 2*np.pi)
            dist = circles[idx, 2] * (1 + np.random.uniform(0, 1))
            candidate = circles[idx, :2] + dist * np.array([np.cos(angle), np.sin(angle)])

            if not (0 <= candidate[0] <= 1 and 0 <= candidate[1] <= 1):
                continue

            min_dist = min(candidate[0], 1 - candidate[0], candidate[1], 1 - candidate[1])
            for m in active:
                dist = np.linalg.norm(circles[m, :2] - candidate) - circles[m, 2]
                if dist < min_dist:
                    min_dist = dist

            if min_dist > best_r:
                best_r = min_dist
                best_pos = candidate

        if best_r > 0:
            circles[i, :2] = best_pos
            circles[i, 2] = best_r * 0.9
            active.append(i)

    # Hybrid optimization
    for iteration in range(1000):
        temperature = 0.2 * (1 - iteration/1000)

        # Simulated annealing phase
        if iteration % 2 == 0:
            for i in range(n):
                if np.random.random() < temperature:
                    angle = np.random.uniform(0, 2*np.pi)
                    step = temperature * 0.3
                    candidate = circles[i, :2] + step * np.array([np.cos(angle), np.sin(angle)])
                    candidate = np.clip(candidate, 0, 1)

                    min_dist = min(candidate[0], 1 - candidate[0], candidate[1], 1 - candidate[1])
                    for j in range(n):
                        if i == j:
                            continue
                        dist = np.linalg.norm(circles[j, :2] - candidate) - circles[j, 2]
                        if dist < min_dist:
                            min_dist = dist

                    if min_dist > circles[i, 2] * 0.9:
                        circles[i, :2] = candidate

        # Lloyd's algorithm phase
        else:
            points = circles[:, :2]
            vor = Voronoi(points)

            for i in range(n):
                region = vor.regions[vor.point_region[i]]
                if -1 not in region and len(region) > 0:
                    vertices = vor.vertices[region]
                    centroid = np.mean(vertices, axis=0)
                    centroid = np.clip(centroid, 0, 1)

                    min_dist = min(centroid[0], 1 - centroid[0], centroid[1], 1 - centroid[1])
                    for j in range(n):
                        if i == j:
                            continue
                        dist = np.linalg.norm(circles[j, :2] - centroid) - circles[j, 2]
                        if dist < min_dist:
                            min_dist = dist

                    if min_dist > circles[i, 2] * 0.95:
                        circles[i, :2] = centroid

        # Dynamic radius expansion
        for i in range(n):
            min_dist = min(circles[i, 0], 1 - circles[i, 0], circles[i, 1], 1 - circles[i, 1])
            for j in range(n):
                if i == j:
                    continue
                dist = np.linalg.norm(circles[j, :2] - circles[i, :2]) - circles[j, 2]
                if dist < min_dist:
                    min_dist = dist

            circles[i, 2] = min_dist * (0.95 + 0.05 * temperature)

    return circles

