def pack_circles(n: int) -> np.ndarray:
    """
    Pack n circles in a unit square to maximize sum of radii.

    Args:
        n: Number of circles to pack

    Returns:
        Numpy array of shape (n, 3) where each row is (x, y, radius)
        All values should be between 0 and 1
        Circles must not overlap

    Important: Set "all" random seeds to 2025, including the packages (such as scipy sub-packages) involving random seeds.
    """
    import numpy as np
    from scipy.spatial import distance

    np.random.seed(2025)
    if n == 0:
        return np.zeros((0, 3))

    # Hexagonal grid initialization
    circles = np.zeros((n, 3))
    rows = int(np.ceil(np.sqrt(n / (2/np.sqrt(3)))))
    if rows == 0:
        rows = 1

    idx = 0
    for i in range(rows):
        for j in range(rows):
            if idx >= n:
                break
            x = (0.5 + j) / rows
            y = (0.5 + i * np.sqrt(3)/2) / rows
            if i % 2 == 1:
                x += 0.5 / rows
            circles[idx, :2] = [x, y]
            idx += 1

    # Initial radius calculation
    for i in range(n):
        r = min(circles[i, 0], 1 - circles[i, 0], circles[i, 1], 1 - circles[i, 1])
        for j in range(n):
            if i == j:
                continue
            d = distance.euclidean(circles[i, :2], circles[j, :2])
            if d < r:
                r = d
        circles[i, 2] = r * 0.5

    # Optimization with repulsive forces and radius expansion
    temp = 1.0
    for iteration in range(1000):
        temp *= 0.995

        # Radius expansion
        for i in range(n):
            max_r = min(circles[i, 0], 1 - circles[i, 0], circles[i, 1], 1 - circles[i, 1])
            for j in range(n):
                if i == j:
                    continue
                d = distance.euclidean(circles[i, :2], circles[j, :2])
                max_r = min(max_r, d - circles[j, 2])
            circles[i, 2] = min(max_r, circles[i, 2] * (1 + 0.05 * temp))

        # Position adjustment with repulsive forces
        for i in range(n):
            force = np.zeros(2)
            for j in range(n):
                if i == j:
                    continue
                vec = circles[i, :2] - circles[j, :2]
                dist = np.linalg.norm(vec)
                if dist < 1e-6:
                    vec = np.random.rand(2) - 0.5
                    dist = np.linalg.norm(vec)
                min_dist = circles[i, 2] + circles[j, 2]
                if dist < min_dist:
                    force += vec / dist * (min_dist - dist) * 0.1

            # Boundary forces
            for dim in [0, 1]:
                if circles[i, dim] - circles[i, 2] < 0:
                    force[dim] += (circles[i, 2] - circles[i, dim]) * 0.2
                if circles[i, dim] + circles[i, 2] > 1:
                    force[dim] -= (circles[i, dim] + circles[i, 2] - 1) * 0.2

            # Apply move with temperature
            step_size = 0.01 * temp
            new_pos = circles[i, :2] + force * step_size
            new_pos = np.clip(new_pos, 0, 1)

            # Check validity
            valid = True
            for j in range(n):
                if i == j:
                    continue
                d = distance.euclidean(new_pos, circles[j, :2])
                if d < circles[i, 2] + circles[j, 2]:
                    valid = False
                    break

            if valid or np.random.rand() < np.exp(-1/temp):
                circles[i, :2] = new_pos

    return circles

