    """
    import numpy as np
    np.random.seed(2025)

    if n == 0:
        return np.zeros((0, 3))

    # Hexagonal grid initialization
    circles = np.zeros((n, 3))
    rows = int(np.ceil(np.sqrt(n / (np.sqrt(3)/2))))
    spacing = 1.0 / (rows + 1)

    idx = 0
    for i in range(rows):
        for j in range(rows):
            if idx >= n:
                break
            x = (j + 0.5 * (i % 2)) * spacing
            y = i * spacing * np.sqrt(3)/2
            if x <= 1 and y <= 1:
                circles[idx, :2] = [x, y]
                circles[idx, 2] = spacing * 0.4
                idx += 1

    # Physics-based optimization
    velocity = np.zeros((n, 2))
    frozen = np.zeros(n, dtype=bool)
    friction = 0.95

    for iteration in range(1000):
        if np.all(frozen):
            break

        # Update positions
        for i in range(n):
            if not frozen[i]:
                circles[i, :2] += velocity[i] * 0.01
                circles[i, :2] = np.clip(circles[i, :2], 0, 1)
                velocity[i] *= friction

        # Handle collisions
        for i in range(n):
            if frozen[i]:
                continue

            # Boundary repulsion
            for dim in [0, 1]:
                for side in [0, 1]:
                    dist = circles[i, dim] if side == 0 else 1 - circles[i, dim]
                    if dist < circles[i, 2]:
                        velocity[i, dim] += (1 if side == 0 else -1) * (circles[i, 2] - dist) * 0.5

        # Circle-circle collisions
        for i in range(n):
            if frozen[i]:
                continue
            for j in range(i+1, n):
                dx = circles[j, 0] - circles[i, 0]
                dy = circles[j, 1] - circles[i, 1]
                dist = np.sqrt(dx*dx + dy*dy)
                min_dist = circles[i, 2] + circles[j, 2]

                if dist < min_dist:
                    nx, ny = dx/dist, dy/dist
                    overlap = min_dist - dist
                    if not frozen[j]:
                        circles[i, :2] -= [nx, ny] * overlap * 0.5
                        circles[j, :2] += [nx, ny] * overlap * 0.5
                        velocity[i] -= [nx, ny] * overlap * 0.1
                        velocity[j] += [nx, ny] * overlap * 0.1
                    else:
                        circles[i, :2] -= [nx, ny] * overlap
                        velocity[i] -= [nx, ny] * overlap * 0.2

        # Update radii and freeze stable circles
        for i in range(n):
            if frozen[i]:
                continue

            min_dist = min(circles[i, 0], 1 - circles[i, 0],
                          circles[i, 1], 1 - circles[i, 1])
