def pack_circles(n: int) -> np.ndarray:
    """
    Pack n circles in a unit square to maximize sum of radii.

    Args:
        n: Number of circles to pack

    Returns:
        Numpy array of shape (n, 3) where each row is (x, y, radius)
        All values should be between 0 and 1
        Circles must not overlap

    Important: Set "all" random seeds to 2025, including the packages (such as scipy sub-packages) involving random seeds.
    """
    import numpy as np
    from scipy.spatial import Voronoi
    from scipy.optimize import minimize

    np.random.seed(2025)
    if n == 0:
        return np.zeros((0, 3))

    circles = np.zeros((n, 3))

    # Hexagonal core packing
    hex_count = min(n, int(np.ceil(np.sqrt(n/0.866))))
    if hex_count > 0:
        spacing = 1.0 / (hex_count + 1)
        hex_radius = spacing * 0.5
        idx = 0
        for i in range(hex_count):
            for j in range(hex_count):
                if idx >= n:
                    break
                x = (i + 0.5 + (j % 2) * 0.5) * spacing
                y = (j + 0.5) * spacing * 0.866
                if x <= 1 and y <= 1:
                    circles[idx] = [x, y, hex_radius]
                    idx += 1

    # Voronoi expansion for remaining circles
    if idx < n:
        points = circles[:idx, :2]
        vor = Voronoi(points)
        new_points = []
        for i, region in enumerate(vor.regions):
            if -1 in region or len(region) == 0:
                continue
            polygon = [vor.vertices[v] for v in region]
            centroid = np.mean(polygon, axis=0)
            if 0 <= centroid[0] <= 1 and 0 <= centroid[1] <= 1:
                new_points.append(centroid)
                if idx + len(new_points) >= n:
                    break

        for point in new_points:
            if idx >= n:
                break
            min_dist = min(np.min(np.linalg.norm(circles[:idx, :2] - point, axis=1)) - circles[:idx, 2])
            circles[idx] = [point[0], point[1], max(0, min(min_dist, 1-point[0], point[0], 1-point[1], point[1]))]
            idx += 1

    # Greedy boundary optimization for remaining circles
    while idx < n:
        best_r = 0
        best_pos = None
        for _ in range(100):
            if np.random.rand() < 0.7:
                side = np.random.randint(4)
                if side == 0:
                    pos = [np.random.rand(), 0]
                elif side == 1:
                    pos = [1, np.random.rand()]
                elif side == 2:
                    pos = [np.random.rand(), 1]
                else:
                    pos = [0, np.random.rand()]
            else:
                pos = np.random.rand(2)

            min_dist = np.min(np.linalg.norm(circles[:idx, :2] - pos, axis=1)) - circles[:idx, 2] if idx > 0 else np.inf
            r = min(pos[0], 1-pos[0], pos[1], 1-pos[1], min_dist)
            if r > best_r:
                best_r = r
                best_pos = pos

        if best_pos is not None:
            circles[idx] = [best_pos[0], best_pos[1], best_r]
            idx += 1

    # Constrained gradient ascent refinement
    def objective(x):
        x = x.reshape(-1, 3)
        return -np.sum(x[:, 2])

    def constraint(x):
        x = x.reshape(-1, 3)
        n = x.shape[0]
        violations = []
        for i in range(n):
            xi, yi, ri = x[i]
            violations.append(ri - xi)
            violations.append(ri - (1 - xi))
            violations.append(ri - yi)
            violations.append(ri - (1 - yi))
            for j in range(i+1, n):
                dij = np.sqrt((x[i,0]-x[j,0])**2 + (x[i,1]-x[j,1])**2)
                violations.append(ri + x[j,2] - dij)
        return np.array(violations)

    bounds = [(0,1)] * (2*n) + [(0,1)] * n
    res = minimize(objective, circles.flatten(), method='SLSQP',
                   bounds=bounds, constraints={'type': 'ineq', 'fun': constraint},
                   options={'maxiter': 100})

    if res.success:
        circles = res.x.reshape(-1, 3)

    return circles

