    rows = int(np.ceil(np.sqrt(n / (2/np.sqrt(3)))))
    if rows == 0:
        rows = 1
    cols = int(np.ceil(n / rows))

    idx = 0
    for i in range(rows):
        for j in range(cols):
            if idx >= n:
                break
            x = (j + 0.5 * (i % 2)) / (cols + 0.5)
            y = (i + 0.5) / (rows + 1)
            r = min(x, 1-x, y, 1-y) * 0.3
            circles[idx] = [x, y, r]
            idx += 1

