    """
    import numpy as np
    from scipy.spatial import Voronoi, Delaunay
    from scipy.optimize import minimize

    np.random.seed(2025)
    if n == 0:
        return np.zeros((0, 3))

    # Poisson disk sampling initialization
    def poisson_disk_samples(k=30):
        points = np.zeros((n, 2))
        points[0] = np.random.rand(2)
        active = [0]

        for i in range(1, n):
            best_dist = -1
            best_point = None

            for _ in range(k):
                idx = np.random.choice(active)
                r = np.random.uniform(0.1, 0.5/np.sqrt(n))
                theta = np.random.uniform(0, 2*np.pi)
                candidate = points[idx] + r * np.array([np.cos(theta), np.sin(theta)])

                if not (0 <= candidate[0] <= 1 and 0 <= candidate[1] <= 1):
                    continue

                min_dist = min(np.linalg.norm(candidate - p) for p in points[:i])
                if min_dist > best_dist:
                    best_dist = min_dist
                    best_point = candidate

            if best_point is not None:
                points[i] = best_point
                active.append(i)
            else:
                active.remove(idx)

        return points

    circles = np.zeros((n, 3))
    circles[:, :2] = poisson_disk_samples()
    circles[:, 2] = np.minimum(np.minimum(circles[:, 0], 1 - circles[:, 0]),
                              np.minimum(circles[:, 1], 1 - circles[:, 1])) * 0.3

    # Voronoi-based optimization
    for epoch in range(5):
        # Delaunay-based global rearrangement
        if epoch > 0:
            tri = Delaunay(circles[:, :2])
            for i in range(n):
                neighbors = set()
                for simplex in tri.simplices:
                    if i in simplex:
                        neighbors.update(simplex)
                neighbors.discard(i)

                if neighbors:
                    center = np.mean(circles[list(neighbors), :2], axis=0)
                    circles[i, :2] = 0.5 * (circles[i, :2] + center)

        # Voronoi cell radius expansion
        vor = Voronoi(circles[:, :2])
        for i in range(n):
            def constraint(x, idx=i):
                for j in range(n):
                    if j == idx:
                        continue
                    if np.linalg.norm(x[:2] - circles[j, :2]) < x[2] + circles[j, 2]:
                        return -1
                return 1

            def objective(x):
                return -x[2]

            x0 = np.array([circles[i, 0], circles[i, 1], circles[i, 2]])
            bounds = [(0, 1), (0, 1), (1e-6, None)]
            cons = {'type': 'ineq', 'fun': constraint}

            res = minimize(objective, x0, bounds=bounds, constraints=cons)
            if res.success:
