    Args:
        n: Number of circles to pack

    Returns:
        Numpy array of shape (n, 3) where each row is (x, y, radius)
        All values should be between 0 and 1
        Circles must not overlap

    Important: Set "all" random seeds to 2025, including the packages (such as scipy sub-packages) involving random seeds.
    """
    import numpy as np
    from scipy.optimize import minimize

    np.random.seed(2025)
    if n == 0:
        return np.zeros((0, 3))

    # Hexagonal grid initialization
    k = int(np.ceil(np.sqrt(n / (np.sqrt(3)/2))))
    spacing = 1.0 / (k + 1)
    circles = np.zeros((n, 3))
    count = 0
    for i in range(k):
        for j in range(k):
            if count >= n:
                break
            x = (j + 0.5 * (i % 2)) * spacing
            y = i * spacing * np.sqrt(3)/2
            if x <= 1 and y <= 1:
                r = min(x, 1-x, y, 1-y)
                circles[count] = [x, y, r * 0.9]
                count += 1

    # Gradient ascent with penalty terms
    def objective(params, circles, index):
        x, y, r = params
        penalty = 0
        # Boundary constraints
        if x - r < 0 or x + r > 1 or y - r < 0 or y + r > 1:
            penalty += 1e6
        # Collision constraints
        for i in range(len(circles)):
            if i == index:
                continue
            dist = np.sqrt((circles[i,0]-x)**2 + (circles[i,1]-y)**2)
            if dist < circles[i,2] + r:
                penalty += 1e6 * (circles[i,2] + r - dist)**2
        return -(r + penalty)

    # Local optimization for each circle
