def pack_circles(n: int) -> np.ndarray:
    """
    Pack n circles in a unit square to maximize sum of radii.

    Args:
        n: Number of circles to pack

    Returns:
        Numpy array of shape (n, 3) where each row is (x, y, radius)
        All values should be between 0 and 1
        Circles must not overlap

    Important: Set "all" random seeds to 2025, including the packages (such as scipy sub-packages) involving random seeds.
    """
    import numpy as np
    from scipy.spatial import Voronoi
    from scipy.optimize import minimize

    np.random.seed(2025)
    if n == 0:
        return np.zeros((0, 3))

    # Poisson disk sampling initialization
    def poisson_disk_sampling(n, radius=0.1, k=30):
        points = np.zeros((n, 2))
        active = []
        grid = {}
        cell_size = radius / np.sqrt(2)

        def get_grid_coords(pt):
            return int(pt[0] // cell_size), int(pt[1] // cell_size)

        def add_point(p):
            nonlocal points
            idx = len(active)
            points[idx] = p
            active.append(idx)
            grid_coords = get_grid_coords(p)
            if grid_coords not in grid:
                grid[grid_coords] = []
            grid[grid_coords].append(idx)

        start = np.random.rand(2)
        add_point(start)

        while len(active) < n and active:
            idx = np.random.choice(active)
            p = points[idx]
            found = False

            for _ in range(k):
                theta = np.random.uniform(0, 2*np.pi)
                r = np.random.uniform(radius, 2*radius)
                new_p = p + r * np.array([np.cos(theta), np.sin(theta)])
                new_p = np.clip(new_p, 0, 1)

                if not (0 <= new_p[0] <= 1 and 0 <= new_p[1] <= 1):
                    continue

                grid_coords = get_grid_coords(new_p)
                valid = True

                for i in range(-2, 3):
                    for j in range(-2, 3):
                        neighbor_coords = (grid_coords[0] + i, grid_coords[1] + j)
                        if neighbor_coords in grid:
                            for neighbor_idx in grid[neighbor_coords]:
                                if np.linalg.norm(new_p - points[neighbor_idx]) < radius:
                                    valid = False
                                    break
                            if not valid:
                                break
                    if not valid:
                        break

                if valid:
                    add_point(new_p)
                    found = True
                    break

            if not found:
                active.remove(idx)

        return points[:n]

    points = poisson_disk_sampling(n)
    circles = np.zeros((n, 3))
    circles[:, :2] = points
    circles[:, 2] = np.minimum(np.minimum(circles[:, 0], 1 - circles[:, 0]),
                              np.minimum(circles[:, 1], 1 - circles[:, 1])) * 0.15

    # Differential evolution with Voronoi-guided optimization
    for iteration in range(1000):
        vor = Voronoi(circles[:, :2])

        for i in range(n):
            def objective(xyr):
                x, y, r = xyr
                if r <= 0 or x < 0 or x > 1 or y < 0 or y > 1:
                    return -np.inf

                current_sum = r
                for j in range(n):
                    if i == j:
                        continue
                    dist = np.sqrt((circles[j,0]-x)**2 + (circles[j,1]-y)**2)
                    if dist < r + circles[j,2]:
                        return -np.inf

                return current_sum

            bounds = [(0, 1), (0, 1), (0, 1)]
            x0 = circles[i].copy()

            # Mutation based on Voronoi neighbors
            neighbors = set()
            for simplex in vor.ridge_points:
                if i in simplex:
                    neighbors.add(simplex[0])
                    neighbors.add(simplex[1])
            neighbors.discard(i)

            if neighbors:
                centroid = np.mean(circles[list(neighbors), :2], axis=0)
                x0[:2] = 0.5 * (x0[:2] + centroid)

            res = minimize(lambda x: -objective(x), x0, bounds=bounds,
                          method='L-BFGS-B', options={'maxiter': 10})

            if res.success and -res.fun > circles[i, 2]:
                circles[i] = res.x

    return circles

