            return int(pt[0] // cell_size), int(pt[1] // cell_size)

        def add_point(p):
            nonlocal points
            idx = len(active)
            points[idx] = p
            active.append(idx)
            grid_coords = get_grid_coords(p)
            if grid_coords not in grid:
