    """
    import numpy as np
    from scipy.spatial import distance
    from scipy.optimize import minimize

    np.random.seed(2025)
    if n == 0:
        return np.zeros((0, 3))

    # Poisson disk sampling initialization
    def poisson_disk_sampling(n, r=0.15, k=30):
        points = np.zeros((n, 2))
        active = []
        grid = {}
        cell_size = r / np.sqrt(2)
        cols = int(np.ceil(1 / cell_size))
        rows = int(np.ceil(1 / cell_size))

        def get_cell(p):
            return int(p[0] // cell_size), int(p[1] // cell_size)

        def generate_point_around(p):
            rad = np.random.uniform(r, 2*r)
            angle = np.random.uniform(0, 2*np.pi)
            return np.array([p[0] + rad * np.cos(angle), p[1] + rad * np.sin(angle)])

        def is_valid(p):
            if not (0 <= p[0] <= 1 and 0 <= p[1] <= 1):
                return False
            cell = get_cell(p)
            for i in range(max(0, cell[0]-2), min(cols, cell[0]+3)):
                for j in range(max(0, cell[1]-2), min(rows, cell[1]+3)):
                    if (i, j) in grid:
                        q = grid[(i, j)]
                        if np.linalg.norm(p - q) < r:
                            return False
            return True

        p0 = np.random.uniform(0, 1, 2)
        points[0] = p0
        active.append(p0)
        grid[get_cell(p0)] = p0

        for i in range(1, n):
            if not active:
                break
            idx = np.random.randint(len(active))
            p = active[idx]
            found = False
            for _ in range(k):
                q = generate_point_around(p)
                if is_valid(q):
                    points[i] = q
                    active.append(q)
                    grid[get_cell(q)] = q
                    found = True
                    break
            if not found:
                active.pop(idx)
        return points

    points = poisson_disk_sampling(n)
    circles = np.zeros((n, 3))
    circles[:, :2] = points
    circles[:, 2] = np.minimum(np.minimum(circles[:, 0], 1 - circles[:, 0]),
                              np.minimum(circles[:, 1], 1 - circles[:, 1])) * 0.15

