    def objective(x, circles, i):
        x = x.reshape(-1, 2)
        penalty = 0
        for j in range(n):
            if j == i:
                continue
            dist = np.sqrt((x[0,0] - circles[j,0])**2 + (x[0,1] - circles[j,1])**2)
            if dist < circles[j,2] + circles[i,2]:
                penalty += (circles[j,2] + circles[i,2] - dist)**2
        return -circles[i,2] + penalty * 100

