def pack_circles(n: int) -> np.ndarray:
    """
    Pack n circles in a unit square to maximize sum of radii.

    Args:
        n: Number of circles to pack

    Returns:
        Numpy array of shape (n, 3) where each row is (x, y, radius)
        All values should be between 0 and 1
        Circles must not overlap

    Important: Set "all" random seeds to 2025, including the packages (such as scipy sub-packages) involving random seeds.
    """
    import numpy as np
    from scipy.spatial import Voronoi
    from scipy.optimize import minimize

    np.random.seed(2025)
    if n == 0:
        return np.zeros((0, 3))

    # Spiral phyllotaxis initialization
    circles = np.zeros((n, 3))
    golden_angle = np.pi * (3 - np.sqrt(5))
    for i in range(n):
        theta = i * golden_angle
        r = np.sqrt(i) / np.sqrt(n) * 0.5
        circles[i, 0] = 0.5 + r * np.cos(theta)
        circles[i, 1] = 0.5 + r * np.sin(theta)

    # Gradient-based radius expansion with Voronoi constraints
    for _ in range(100):
        points = circles[:, :2]
        vor = Voronoi(points)

        for i in range(n):
            region = vor.regions[vor.point_region[i]]
            if -1 in region:
                continue

            vertices = vor.vertices[region]
            min_dist = min(np.linalg.norm(vertices - points[i], axis=1))
            circles[i, 2] = min(min_dist, points[i,0], 1-points[i,0], points[i,1], 1-points[i,1]) * 0.95

    # Boundary-aware jittering
    for iteration in range(500):
        temperature = 1.0 - iteration / 500
        for i in range(n):
            x, y, r = circles[i]
            jitter = np.random.normal(0, 0.02 * temperature, 2)
            new_x = np.clip(x + jitter[0], r, 1-r)
            new_y = np.clip(y + jitter[1], r, 1-r)

            valid = True
            for j in range(n):
                if i == j:
                    continue
                dist = np.sqrt((circles[j,0]-new_x)**2 + (circles[j,1]-new_y)**2)
                if dist < circles[j,2] + r:
                    valid = False
                    break

            if valid:
                circles[i, :2] = [new_x, new_y]

    # Final constrained optimization
    def objective(x):
        return -np.sum(x[2::3])

    def constraint(x, i):
        def f(x_vals):
            xi, yi, ri = x_vals[3*i], x_vals[3*i+1], x_vals[3*i+2]
            return min(xi-ri, 1-xi-ri, yi-ri, 1-yi-ri)
        return f

    def non_overlap(x, i, j):
        def f(x_vals):
            xi, yi, ri = x_vals[3*i], x_vals[3*i+1], x_vals[3*i+2]
            xj, yj, rj = x_vals[3*j], x_vals[3*j+1], x_vals[3*j+2]
            return np.sqrt((xi-xj)**2 + (yi-yj)**2) - (ri + rj)
        return f

    x0 = circles.reshape(-1)
    constraints = []
    for i in range(n):
        constraints.append({'type': 'ineq', 'fun': constraint(x0, i)})
        for j in range(i+1, n):
            constraints.append({'type': 'ineq', 'fun': non_overlap(x0, i, j)})

    bounds = [(0,1)]*(3*n)
    for i in range(2, 3*n, 3):
        bounds[i] = (0, 0.5)

    res = minimize(objective, x0, method='SLSQP', bounds=bounds, constraints=constraints, options={'maxiter': 100})
    circles = res.x.reshape(-1, 3)

    return circles

