    """
    import numpy as np

    np.random.seed(2025)
    if n == 0:
        return np.zeros((0, 3))

    # Hexagonal grid initialization
    circles = np.zeros((n, 3))
    if n == 1:
        circles[0] = [0.5, 0.5, 0.5]
        return circles

    rows = int(np.ceil(np.sqrt(n / (np.sqrt(3)/2))))
    spacing = 1.0 / (rows + 1)
    idx = 0
    for i in range(rows):
        for j in range(rows):
            if idx >= n:
                break
            x = (j + 0.5 * (i % 2)) * spacing * np.sqrt(3)
            y = i * spacing
            if x <= 1.0 and y <= 1.0:
                circles[idx, :2] = [x, y]
                idx += 1

    # Initial radii based on nearest neighbor
    for i in range(n):
        min_dist = min(circles[i,0], 1-circles[i,0], circles[i,1], 1-circles[i,1])
        for j in range(n):
            if i == j:
                continue
            dist = np.sqrt((circles[j,0]-circles[i,0])**2 + (circles[j,1]-circles[i,1])**2)
            min_dist = min(min_dist, dist)
        circles[i,2] = min_dist * 0.5

    # Force-based optimization
    for iteration in range(5000):
        # Calculate repulsive forces
        forces = np.zeros((n, 2))
        for i in range(n):
            for j in range(i+1, n):
                dx = circles[j,0] - circles[i,0]
                dy = circles[j,1] - circles[i,1]
                dist = np.sqrt(dx*dx + dy*dy)
                min_dist = circles[i,2] + circles[j,2]
                if dist < min_dist:
                    force = (min_dist - dist) / dist
                    forces[i,0] -= dx * force
                    forces[i,1] -= dy * force
                    forces[j,0] += dx * force
                    forces[j,1] += dy * force

        # Boundary forces
        for i in range(n):
            x, y, r = circles[i]
            if x - r < 0:
                forces[i,0] += (r - x) * 10
            if x + r > 1:
                forces[i,0] -= (x + r - 1) * 10
            if y - r < 0:
                forces[i,1] += (r - y) * 10
            if y + r > 1:
                forces[i,1] -= (y + r - 1) * 10

        # Update positions with adaptive step size
        step = 0.1 * (1 - iteration/5000)
        for i in range(n):
            force_mag = np.sqrt(forces[i,0]**2 + forces[i,1]**2)
            if force_mag > 0:
                circles[i,0] = np.clip(circles[i,0] + step * forces[i,0]/force_mag, 0, 1)
                circles[i,1] = np.clip(circles[i,1] + step * forces[i,1]/force_mag, 0, 1)

        # Periodic radius rescaling
        if iteration % 100 == 0:
            scale_factor = 1.0
            for i in range(n):
                x, y, r = circles[i]
                max_r = min(x, 1-x, y, 1-y)
                for j in range(n):
                    if i == j:
                        continue
                    dist = np.sqrt((circles[j,0]-x)**2 + (circles[j,1]-y)**2)
                    max_r = min(max_r, dist - circles[j,2])
                scale_factor = min(scale_factor, max_r / r)

            if scale_factor > 1.0:
                circles[:,2] *= scale_factor

    return circles

