        All values should be between 0 and 1
        Circles must not overlap

    Important: Set "all" random seeds to 2025, including the packages (such as scipy sub-packages) involving random seeds.
    """
    import numpy as np
    from scipy.spatial import distance

    np.random.seed(2025)
    if n == 0:
        return np.zeros((0, 3))

    # Hexagonal grid initialization
    circles = np.zeros((n, 3))
    if n == 1:
        circles[0] = [0.5, 0.5, 0.5]
        return circles

    k = int(np.ceil(np.sqrt(n / (np.sqrt(3)/2))))
    spacing = 1.0 / (k + 1)
    idx = 0
    for i in range(k):
        for j in range(k):
            if idx >= n:
                break
            x = spacing * (j + 1)
            y = spacing * (i + 1) if j % 2 == 0 else spacing * (i + 1.5)
            if y > 1.0:
                continue
            circles[idx, :2] = [x, y]
            circles[idx, 2] = min(x, 1-x, y, 1-y) * 0.9
            idx += 1
            if idx >= n:
                break

    # Differential evolution with niching
    population = np.tile(circles, (5, 1, 1))
    best_fitness = np.zeros(5)

    for iteration in range(3000):
        mutation_rate = 0.2 + 0.3 * np.cos(np.pi * iteration / 3000)
        perturbation_cycle = iteration % 200 == 0

        for p in range(5):
            if perturbation_cycle and np.random.random() < 0.3:
                # Large perturbation
                for i in range(n):
                    if np.random.random() < 0.1:
                        population[p, i, 0] = np.random.uniform(0, 1)
                        population[p, i, 1] = np.random.uniform(0, 1)

            for i in range(n):
                # Mutation and crossover
                if np.random.random() < mutation_rate:
                    a, b, c = np.random.choice(5, 3, replace=False)
                    mutant = population[a, i] + 0.5 * (population[b, i] - population[c, i])
                    mutant[0] = np.clip(mutant[0], 0, 1)
                    mutant[1] = np.clip(mutant[1], 0, 1)

                    # Radius expansion with niching
                    max_r = min(mutant[0], 1-mutant[0], mutant[1], 1-mutant[1])
                    for j in range(n):
                        if i == j:
                            continue
                        dist = distance.euclidean(mutant[:2], population[p, j, :2])
                        max_r = min(max_r, dist - population[p, j, 2])

                    mutant[2] = max_r
                    population[p, i] = mutant

        # Evaluate fitness and selection
        for p in range(5):
            valid = True
            for i in range(n):
                x, y, r = population[p, i]
                if r <= 0 or x < 0 or x > 1 or y < 0 or y > 1:
                    valid = False
                    break
                for j in range(i+1, n):
                    dist = distance.euclidean(population[p, i, :2], population[p, j, :2])
                    if dist < population[p, i, 2] + population[p, j, 2]:
                        valid = False
                        break
                if not valid:
                    break

            if valid:
                current_fitness = np.sum(population[p, :, 2])
                if current_fitness > best_fitness[p]:
                    best_fitness[p] = current_fitness
            else:
                population[p] = np.copy(circles)

    best_idx = np.argmax(best_fitness)
    return population[best_idx]

