    Important: Set "all" random seeds to 2025, including the packages (such as scipy sub-packages) involving random seeds.
    """
    import numpy as np
    from scipy.spatial import Voronoi
    from scipy.optimize import minimize
    import random

    np.random.seed(2025)
    random.seed(2025)

    if n == 0:
        return np.zeros((0, 3))

    # Poisson disk sampling initialization
    def poisson_disk_sampling(n, k=30):
        points = np.zeros((n, 2))
        active = []
        grid = {}
        cell_size = 1.0 / np.sqrt(n)
        cols = int(1.0 / cell_size) + 1
        rows = int(1.0 / cell_size) + 1

        def get_cell(p):
            return (int(p[0]/cell_size), int(p[1]/cell_size))

        def add_point(p):
            nonlocal points
            idx = len(active)
            if idx < n:
                points[idx] = p
                active.append(idx)
                cell = get_cell(p)
                grid.setdefault(cell, []).append(idx)

