            idx = random.choice(active)
            p = points[idx]
            found = False

            for _ in range(k):
                theta = random.uniform(0, 2*np.pi)
                r = random.uniform(cell_size, 2*cell_size)
                q = p + r * np.array([np.cos(theta), np.sin(theta)])

                if 0 <= q[0] <= 1 and 0 <= q[1] <= 1:
                    valid = True
                    q_cell = get_cell(q)
                    for i in range(max(0, q_cell[0]-2), min(cols, q_cell[0]+3)):
